// The browser sends the whole contact. Split it into the calls that follow,
// so each node has exactly what it needs and nothing downstream has to
// reach back into the raw body.
const b = $input.first().json.body || $input.first().json;
if (!b.properties || !b.properties.email) {
  throw new Error('No email on the payload. HubSpot needs one to dedupe on.');
}
return [{ json: {
  email: b.properties.email,
  properties: b.properties,
  notes: b.notes || [],
  draft: b.draft || null,
  internalNote: b.internalNote || null,
} }];

// A 404 from the upsert means the contact does not exist yet, so create
// it. Any other non-2xx is a real failure and should stop the run.
const r = $input.first().json;
const src = $('Shape the payload').first().json;
if (r.statusCode >= 200 && r.statusCode < 300) {
  return [{ json: { contactId: r.body.id, created: false, ...src } }];
}
if (r.statusCode === 404) return [{ json: { contactId: null, created: true, ...src } }];
throw new Error(`HubSpot returned ${r.statusCode}: ${JSON.stringify(r.body).slice(0, 300)}`);

// One item per note, each associated to the contact. Association type 202
// is note-to-contact. The internal read rides along as one more note, so
// the rep's reasoning sits on the timeline beside the draft and never
// inside the email the prospect would receive.
const src = $('Shape the payload').first().json;
let contactId = $json.contactId;
if (!contactId && $json.id) contactId = $json.id;
const all = [...(src.notes || [])];
if (src.internalNote) all.push({ timestamp: new Date().toISOString(), body: src.internalNote.body });
return all.map(n => ({ json: {
  contactId,
  properties: { hs_timestamp: n.timestamp, hs_note_body: n.body },
  associations: [{ to: { id: contactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 202 }] }],
} }));
